create or replace function public.business_create_partner_program(p_name text,p_partner_business_id uuid) returns uuid language plpgsql security definer set search_path to 'public','pg_temp' as $$ declare v_id uuid; begin if not exists(select 1 from public.business_members where business_id=p_partner_business_id and user_id=auth.uid() and role in ('owner','admin','manager')) then raise exception 'business_admin_required'; end if; insert into public.partner_programs(name,business_id,enabled,preferred_access) values(trim(p_name),p_partner_business_id,false,false) returning id into v_id; return v_id; end; $$;
create or replace function public.business_add_program_member(p_partner_program_id uuid,p_user_id uuid) returns uuid language plpgsql security definer set search_path to 'public','pg_temp' as $$ declare v_id uuid; begin if not exists(select 1 from public.partner_programs pp join public.business_members bm on bm.business_id=pp.business_id where pp.id=p_partner_program_id and bm.user_id=auth.uid() and bm.role in ('owner','admin','manager')) then raise exception 'business_admin_required'; end if; if p_user_id is null then raise exception 'user_required'; end if; insert into public.partner_program_memberships(partner_program_id,user_id,status,source) values(p_partner_program_id,p_user_id,'active','business_program') on conflict(partner_program_id,user_id) do update set status='active',expires_at=null returning id into v_id; return v_id; end; $$;
create or replace function public.business_request_partner_agreement(p_partner_program_id uuid,p_partner_business_id uuid) returns uuid language plpgsql security definer set search_path to 'public','pg_temp' as $$ declare v_id uuid; v_owner uuid; begin select business_id into v_owner from public.partner_programs where id=p_partner_program_id; if v_owner is null then raise exception 'program_not_found'; end if; if not exists(select 1 from public.business_members where business_id=v_owner and user_id=auth.uid() and role in ('owner','admin','manager')) then raise exception 'business_admin_required'; end if; if not exists(select 1 from public.businesses where id=p_partner_business_id) then raise exception 'partner_business_does_not_exist'; end if; insert into public.partner_agreements(partner_program_id,partner_business_id,status) values(p_partner_program_id,p_partner_business_id,'pending') returning id into v_id; return v_id; end; $$;
create or replace function public.business_enroll_program_user(p_partner_program_id uuid,p_user_id uuid) returns uuid language plpgsql security definer set search_path to 'public','pg_temp' as $$ declare v_id uuid; v_tier text; begin if not exists(select 1 from public.partner_programs pp join public.business_members bm on bm.business_id=pp.business_id where pp.id=p_partner_program_id and bm.user_id=auth.uid() and bm.role in ('owner','admin','manager')) then raise exception 'business_admin_required'; end if; select lower(subscription_tier) into v_tier from public.profiles where id=p_user_id; if v_tier not in ('premium','fleet','enterprise') then raise exception 'user tier is not eligible'; end if; insert into public.partner_program_memberships(partner_program_id,user_id,status,source) values(p_partner_program_id,p_user_id,'active','business_program') on conflict(partner_program_id,user_id) do update set status='active',expires_at=null returning id into v_id; return v_id; end; $$;
create or replace function public.business_remove_program_location(p_partner_program_id uuid,p_location_id uuid) returns boolean language plpgsql security definer set search_path to 'public','pg_temp' as $$ begin if not exists(select 1 from public.partner_programs pp join public.business_members bm on bm.business_id=pp.business_id join public.locations l on l.business_id=pp.business_id where pp.id=p_partner_program_id and l.id=p_location_id and bm.user_id=auth.uid() and bm.role in ('owner','admin','manager')) then raise exception 'business_admin_required'; end if; update public.partner_program_locations set status='revoked' where partner_program_id=p_partner_program_id and location_id=p_location_id; return true; end; $$;
create or replace function public.business_revoke_program_member(p_partner_program_id uuid,p_user_id uuid) returns boolean language plpgsql security definer set search_path to 'public','pg_temp' as $$ begin if not exists(select 1 from public.partner_programs pp join public.business_members bm on bm.business_id=pp.business_id where pp.id=p_partner_program_id and bm.user_id=auth.uid() and bm.role in ('owner','admin','manager')) then raise exception 'business_admin_required'; end if; update public.partner_program_memberships set status='revoked' where partner_program_id=p_partner_program_id and user_id=p_user_id; return true; end; $$;
